DEFAULT_SETTINGS = {'primary': '#101116', 'secondary': '#a394ff', 'shortcut': 'F11', 'fontSize': 14}
DEFAULT_APPS = [('Discord','https://discord.com/app'), ('WhatsApp','https://web.whatsapp.com'),
 ('X','https://x.com'), ('TikTok','https://www.tiktok.com'), ('Gmail','https://mail.google.com'),
 ('Telegram','https://web.telegram.org'), ('Instagram','https://www.instagram.com'), ('YouTube','https://www.youtube.com')]

def normalize_url(value):
    value = value.strip()
    if '://' not in value:
        value = 'https://' + value
    parsed = urlsplit(value)
    if parsed.scheme not in ('http', 'https') or not parsed.hostname or parsed.username or parsed.password:
        raise ValueError('Enter a valid HTTP or HTTPS URL without embedded credentials.')
    try:
        parsed.hostname.encode('idna')
        parsed.port
    except (ValueError, UnicodeError) as exc:
        raise ValueError('The URL contains an invalid host or port.') from exc
    if any(c.isspace() or ord(c) < 32 for c in value):
        raise ValueError('URLs cannot contain spaces or control characters.')
    return value

def decode_platform_qr(raw):
    """Decode locally. Only website QR codes can become platform addresses."""
    try:
        import zxingcpp
        from PIL import Image, UnidentifiedImageError
    except ImportError as exc:
        raise ValueError('QR import needs two small packages. Run: py -m pip install zxing-cpp Pillow') from exc
    if not raw or len(raw) > 10 * 1024 * 1024:
        raise ValueError('Choose a QR picture smaller than 10 MB.')
    try:
        with Image.open(io.BytesIO(raw)) as picture:
            width, height = picture.size
            if width > 8192 or height > 8192 or width * height > 16000000:
                raise ValueError('Choose a QR picture up to 16 megapixels.')
            results = zxingcpp.read_barcodes(picture.convert('RGB'), formats=zxingcpp.BarcodeFormat.QRCode)
    except (UnidentifiedImageError, OSError, Image.DecompressionBombError) as exc:
        raise ValueError('This image could not be opened. Choose a PNG, JPG, WebP or BMP.') from exc
    urls = []
    for result in results:
        text = result.text.strip()
        # Login challenges, Wi-Fi and arbitrary text are not website shortcuts.
        if not re.match(r'^(?:https?://|www\.)', text, re.IGNORECASE):
            continue
        try:
            url = normalize_url(text)
        except ValueError:
            continue
        if len(url) <= 2048 and url not in urls:
            urls.append(url)
    if len(urls) > 1:
        raise ValueError('Several website QR codes were found. Crop the image to one code and try again.')
    if not urls:
        raise ValueError('No website QR code was found. Choose a clear code containing an HTTP or HTTPS link. Sign-in and Wi-Fi QR codes cannot be added as platforms.')
    return urls[0]


class QRSignals(QObject):
    finished = pyqtSignal(bool, str)


class QRDecodeTask(QRunnable):
    def __init__(self, path):
        super().__init__()
        self.path = path
        self.signals = QRSignals()

    def run(self):
        try:
            with open(self.path, 'rb') as stream:
                raw = stream.read(10 * 1024 * 1024 + 1)
            url = decode_platform_qr(raw)
        except Exception as exc:
            self.signals.finished.emit(False, str(exc))
        else:
            self.signals.finished.emit(True, url)


def sanitize_picture(raw):
    if not raw or len(raw) > 10 * 1024 * 1024:
        raise ValueError('Choose a picture smaller than 10 MB.')
    buffer = QBuffer()
    buffer.setData(QByteArray(raw))
    buffer.open(QIODevice.OpenModeFlag.ReadOnly)
    reader = QImageReader(buffer)
    reader.setAutoTransform(True)
    size = reader.size()
    if (not size.isValid() or size.width() > 8192 or size.height() > 8192
            or size.width() * size.height() > 16000000):
        raise ValueError('Choose a supported picture up to 16 megapixels.')
    image = reader.read()
    if image.isNull():
        raise ValueError('This picture could not be opened.')
    image = image.scaled(128, 128, Qt.AspectRatioMode.KeepAspectRatio,
                         Qt.TransformationMode.SmoothTransformation)
    canvas = QImage(128, 128, QImage.Format.Format_ARGB32_Premultiplied)
    canvas.fill(Qt.GlobalColor.transparent)
    painter = QPainter(canvas)
    painter.drawImage((128-image.width())//2, (128-image.height())//2, image)
    painter.end()
    encoded = QByteArray()
    output = QBuffer(encoded)
    output.open(QIODevice.OpenModeFlag.WriteOnly)
    if not canvas.save(output, 'PNG'):
        raise ValueError('Could not prepare this picture.')
    return 'data:image/png;base64,' + base64.b64encode(bytes(encoded)).decode('ascii')

def validate_picture(uri):
    prefix = 'data:image/png;base64,'
    if not isinstance(uri, str) or not uri.startswith(prefix) or len(uri) > 256000:
        raise ValueError('Choose a valid app picture using Choose picture.')
    try:
        raw = base64.b64decode(uri[len(prefix):], validate=True)
        buffer = QBuffer()
        buffer.setData(QByteArray(raw))
        buffer.open(QIODevice.OpenModeFlag.ReadOnly)
        reader = QImageReader(buffer, b'PNG')
        if reader.size().width() != 128 or reader.size().height() != 128 or reader.read().isNull():
            raise ValueError('Picture must be a 128-pixel PNG.')
        return uri
    except (ValueError, TypeError) as exc:
        raise ValueError('This app picture is invalid. Please choose it again.') from exc

def choose_picture(parent):
    path, _ = QFileDialog.getOpenFileName(parent, 'Choose app picture', '',
        'Pictures (*.png *.jpg *.jpeg *.webp *.bmp *.ico)')
    if not path:
        return None
    if Path(path).stat().st_size > 10 * 1024 * 1024:
        raise ValueError('Choose a picture smaller than 10 MB.')
    return sanitize_picture(Path(path).read_bytes()), Path(path).name

def app_record(name, url, identifier=None, icon=None):
    name = name.strip()
    if not name or len(name) > 80:
        raise ValueError('Choose a name between 1 and 80 characters.')
    url = normalize_url(url)
    domain = urlsplit(url).hostname.encode('idna').decode('ascii')
    # Keep custom pictures. Refresh old automatic WhatsApp icons as well.
    if icon is not None and not isinstance(icon, str):
        raise ValueError('App pictures must be valid image data.')
    if icon and not icon.startswith('https://www.google.com/s2/favicons?'):
        picture = validate_picture(icon)
    elif domain == 'whatsapp.com' or domain.endswith('.whatsapp.com'):
        picture = WHATSAPP_ICON
    else:
        picture = 'https://www.google.com/s2/favicons?domain=' + quote(domain, safe='') + '&sz=128'
    return {'id': identifier or uuid.uuid4().hex, 'name': name, 'url': url, 'icon': picture}

class Store:
    def __init__(self, path):
        self.path = path
        self.settings = dict(DEFAULT_SETTINGS)
        self.apps = [app_record(*a) for a in DEFAULT_APPS]
        if path.exists():
            try:
                data = json.loads(path.read_text(encoding='utf-8'))
                if not isinstance(data, dict) or not isinstance(data.get('apps'), list):
                    raise ValueError('Invalid workspace file.')
                self.apps = [app_record(a['name'], a['url'], a.get('id'), a.get('icon')) for a in data['apps']]
                ids = [a['id'] for a in self.apps]
                if any(not isinstance(i, str) for i in ids) or len(set(ids)) != len(ids):
                    raise ValueError('App IDs must be unique strings.')
                settings = data.get('settings', {})
                # Older versions allowed combinations now used for tab navigation.
                if isinstance(settings, dict) and settings.get('shortcut') in ('Ctrl+Tab', 'Ctrl+Shift+Tab', 'Ctrl+W'):
                    settings = dict(settings, shortcut='F11')
                self.settings = validate_settings(settings)
            except (OSError, ValueError, TypeError, KeyError) as exc:
                raise RuntimeError('Cannot read workspace_apps.json. Restore or repair the file; it has not been overwritten.') from exc
        else:
            self.save()

    def save(self):
        self.path.parent.mkdir(parents=True, exist_ok=True)
        file = QSaveFile(str(self.path))
        if not file.open(QIODevice.OpenModeFlag.WriteOnly):
            raise OSError(file.errorString())
        payload = json.dumps({'version': 1, 'apps': self.apps, 'settings': self.settings}, indent=2).encode()
        if file.write(payload) != len(payload) or not file.commit():
            raise OSError(file.errorString())
        try:
            self.path.chmod(0o600)
        except OSError:
            pass

def validate_settings(raw):
    result = dict(DEFAULT_SETTINGS)
    for key in ('primary', 'secondary'):
        value = raw.get(key, result[key])
        if not isinstance(value, str) or not re.fullmatch(r'#[0-9a-fA-F]{6}', value):
            raise ValueError('Colors must be six-digit hex values.')
        result[key] = value
    value = raw.get('shortcut', 'F11')
    if not isinstance(value, str):
        raise ValueError('Invalid shortcut.')
    sequence = QKeySequence.fromString(value, QKeySequence.SequenceFormat.PortableText)
    if sequence.isEmpty() or sequence.count() != 1 or sequence.toString() in ('Ctrl+H', 'Ctrl+Tab', 'Ctrl+Shift+Tab', 'Ctrl+W'):
        raise ValueError('Choose one key combination other than Ctrl+H, Ctrl+Tab, Ctrl+Shift+Tab, or Ctrl+W.')
    if sequence[0].key() in (Qt.Key.Key_unknown, Qt.Key.Key_Control, Qt.Key.Key_Shift, Qt.Key.Key_Alt, Qt.Key.Key_Meta):
        raise ValueError('Choose a key, optionally with modifiers.')
    size = raw.get('fontSize', 14)
    if type(size) is not int or not 12 <= size <= 20:
        raise ValueError('Font size must be a whole number from 12 to 20.')
    result['fontSize'] = size
    result['shortcut'] = sequence.toString(QKeySequence.SequenceFormat.PortableText)
    return result

class Bridge(QObject):
    stateChanged = pyqtSignal(str)
    viewActivated = pyqtSignal(str)
    result = pyqtSignal(str, bool, str)
    iconChosen = pyqtSignal(str, str)
    qrDecoded = pyqtSignal(bool, str)

    def __init__(self, window):
        super().__init__(window)
        self.window = window
        self.qr_task = None

    @pyqtSlot(bool)
    def recordingShortcut(self, active):
        self.window.recording = active

    @pyqtSlot()
    def ready(self):
        self.window.broadcast()

    @pyqtSlot(str)
    def navigate(self, view):
        self.window.navigate(view)

    @pyqtSlot(str, bool)
    def openApp(self, identifier, floating):
        self.window.open_app(identifier, floating)

    @pyqtSlot(str)
    def launchApp(self, identifier):
        self.window.launch_app(identifier)

    @pyqtSlot()
    def pickIcon(self):
        try:
            with self.window.paused_shortcuts():
                selection = choose_picture(self.window)
        except (OSError, ValueError) as exc:
            self.result.emit('add', False, str(exc))
            return
        if selection:
            self.iconChosen.emit(*selection)

    @pyqtSlot()
    def scanPlatformQR(self):
        if self.qr_task is not None:
            return
        with self.window.paused_shortcuts():
            path, _ = QFileDialog.getOpenFileName(self.window, 'Choose a website QR code', '',
                'QR pictures (*.png *.jpg *.jpeg *.webp *.bmp)')
        if not path:
            self.qrDecoded.emit(False, '')
            return
        task = QRDecodeTask(path)
        self.qr_task = task
        task.signals.finished.connect(self.qr_finished)
        QThreadPool.globalInstance().start(task)

    @pyqtSlot(bool, str)
    def qr_finished(self, success, value):
        self.qr_task = None
        self.qrDecoded.emit(success, value)

    @pyqtSlot(str)
    def editAppIcon(self, identifier):
        self.window.edit_app_icon(identifier)

    @pyqtSlot(str, str)
    def addApp(self, name, url):
        self.add_app(name, url)

    @pyqtSlot(str, str, str)
    def addAppWithIcon(self, name, url, icon):
        self.add_app(name, url, icon)

    def add_app(self, name, url, icon=None):
        store = self.window.store
        old = list(store.apps)
        try:
            app = app_record(name, url, icon=icon)
            if any(a['url'].rstrip('/') == app['url'].rstrip('/') for a in old):
                raise ValueError('This URL is already in your workspace.')
            store.apps.append(app)
            store.save()
        except (ValueError, OSError) as exc:
            store.apps = old
            self.result.emit('add', False, str(exc))
            return
        self.window.rebuild_menu()
        self.window.broadcast()
        self.result.emit('add', True, 'Platform added.')
        self.window.navigate('dashboard')
        if self.window.tray.isVisible():
            self.window.tray.showMessage('Social Workspace', app['name'] + ' was added.', QSystemTrayIcon.MessageIcon.Information, 4000)

    @pyqtSlot(str)
    def removeApp(self, identifier):
        self.window.confirm_remove_app(identifier)

    @pyqtSlot(str)
    def saveSettings(self, payload):
        old = dict(self.window.store.settings)
        try:
            self.window.store.settings = validate_settings(json.loads(payload))
            self.window.store.save()
        except (ValueError, TypeError, AttributeError, OSError) as exc:
            self.window.store.settings = old
            self.result.emit('settings', False, str(exc))
            return
        self.window.apply_settings()
        self.window.broadcast()
        self.result.emit('settings', True, 'Settings saved.')

class BrowserPage(QWebEnginePage):
    """Remote content never receives the privileged workspace channel."""
    def __init__(self, profile, parent, popup_factory):
        super().__init__(profile, parent)
        self.popup_factory = popup_factory

    def acceptNavigationRequest(self, url, kind, main):
        return url.scheme() in ('https', 'http', 'about', 'blob', 'data')

    def createWindow(self, kind):
        return self.popup_factory().page()

class LocalPage(QWebEnginePage):
    def acceptNavigationRequest(self, url, kind, main):
        # Never navigate a privileged page to a remote document.
        return not main or url.scheme() in ('data', 'about') or url.toString().rstrip('/') == 'http://localhost'

class DraggableBar(QWidget):
    """Drag empty caption space using the OS window manager when available."""
    def __init__(self, owner, prepare_move=None, toggle_size=None):
        super().__init__()
        self.owner = owner
        self.prepare_move = prepare_move
        self.toggle_size = toggle_size
        self._drag_offset = None
        self._native_move = False

    def mousePressEvent(self, event):
        if event.button() != Qt.MouseButton.LeftButton:
            return super().mousePressEvent(event)
        pointer = event.globalPosition().toPoint()
        fraction = max(0.05, min(0.95, event.position().x() / max(1, self.width())))
        restore = self.owner.isFullScreen() or self.owner.isMaximized()
        if self.prepare_move:
            self.prepare_move()
        if restore:
            self.owner.move(pointer.x() - int(self.owner.width() * fraction), pointer.y() - 18)
        self._drag_offset = pointer - self.owner.frameGeometry().topLeft()
        handle = self.owner.windowHandle()
        self._native_move = bool(handle and handle.startSystemMove())
        event.accept()

    def mouseMoveEvent(self, event):
        if self._drag_offset is not None and event.buttons() & Qt.MouseButton.LeftButton:
            if not self._native_move:
                self.owner.move(event.globalPosition().toPoint() - self._drag_offset)
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        self._drag_offset = None
        self._native_move = False
        super().mouseReleaseEvent(event)

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton and self.toggle_size:
            self._drag_offset = None
            self.toggle_size()
            event.accept()
        else:
            super().mouseDoubleClickEvent(event)


class AppWindow(QMainWindow):
    def __init__(self):
        super().__init__(None, Qt.WindowType.Window | Qt.WindowType.FramelessWindowHint)
        self.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose)
        self.setMinimumSize(480, 360)
        self.grip = QSizeGrip(self)
        self.grip.setFixedSize(15, 15)
        self.grip.setToolTip('Resize window')

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.grip.move(self.width()-15, self.height()-15)
        self.grip.setVisible(not self.isMaximized() and not self.isFullScreen())
        self.grip.raise_()


